package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo.As;
import com.fasterxml.jackson.annotation.JsonTypeInfo.Id;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.SerializationConfig;
import com.fasterxml.jackson.databind.annotation.NoClass;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.jsontype.*;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.jsontype.impl.AsArrayTypeSerializer;
import com.fasterxml.jackson.databind.jsontype.impl.AsExistingPropertyTypeSerializer;
import com.fasterxml.jackson.databind.jsontype.impl.AsExternalTypeSerializer;
import com.fasterxml.jackson.databind.jsontype.impl.AsPropertyTypeSerializer;
import com.fasterxml.jackson.databind.jsontype.impl.AsWrapperTypeSerializer;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Collections;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.when;

public class StdTypeResolverBuilder_buildTypeSerializer_TriageGen0Test {

    private SerializationConfig config;
    private JavaType baseType;
    private TypeIdResolver mockIdResolver;

    @Before
    public void setUp() {
        config = Mockito.mock(SerializationConfig.class);
        baseType = Mockito.mock(JavaType.class);
        mockIdResolver = Mockito.mock(TypeIdResolver.class);
    }

    @Test
    public void testBuildTypeSerializer_IdNone_ReturnsNull() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder().init(Id.NONE, mockIdResolver);
        TypeSerializer result = builder.buildTypeSerializer(config, baseType, Collections.emptyList());
        Assert.assertNull(result);
    }

    @Test
    public void testBuildTypeSerializer_WrapperArray() {
        StdTypeResolverBuilder builder = spy(new StdTypeResolverBuilder());
        builder.init(Id.NAME, mockIdResolver).inclusion(As.WRAPPER_ARRAY);

        doReturn(mockIdResolver).when(builder).idResolver(any(), any(), any(), anyBoolean(), anyBoolean());

        TypeSerializer result = builder.buildTypeSerializer(config, baseType, Collections.emptyList());
        Assert.assertTrue(result instanceof AsArrayTypeSerializer);
    }

    @Test
    public void testBuildTypeSerializer_Property() {
        String propName = "type";
        StdTypeResolverBuilder builder = spy(new StdTypeResolverBuilder());
        builder.init(Id.NAME, mockIdResolver).inclusion(As.PROPERTY).typeProperty(propName);

        doReturn(mockIdResolver).when(builder).idResolver(any(), any(), any(), anyBoolean(), anyBoolean());

        TypeSerializer result = builder.buildTypeSerializer(config, baseType, Collections.emptyList());
        Assert.assertTrue(result instanceof AsPropertyTypeSerializer);
    }

    @Test
    public void testBuildTypeSerializer_WrapperObject() {
        StdTypeResolverBuilder builder = spy(new StdTypeResolverBuilder());
        builder.init(Id.NAME, mockIdResolver).inclusion(As.WRAPPER_OBJECT);

        doReturn(mockIdResolver).when(builder).idResolver(any(), any(), any(), anyBoolean(), anyBoolean());

        TypeSerializer result = builder.buildTypeSerializer(config, baseType, Collections.emptyList());
        Assert.assertTrue(result instanceof AsWrapperTypeSerializer);
    }

    @Test
    public void testBuildTypeSerializer_ExternalProperty() {
        String propName = "extProp";
        StdTypeResolverBuilder builder = spy(new StdTypeResolverBuilder());
        builder.init(Id.NAME, mockIdResolver).inclusion(As.EXTERNAL_PROPERTY).typeProperty(propName);

        doReturn(mockIdResolver).when(builder).idResolver(any(), any(), any(), anyBoolean(), anyBoolean());

        TypeSerializer result = builder.buildTypeSerializer(config, baseType, Collections.emptyList());
        Assert.assertTrue(result instanceof AsExternalTypeSerializer);
    }

    @Test
    public void testBuildTypeSerializer_ExistingProperty() {
        String propName = "existProp";
        StdTypeResolverBuilder builder = spy(new StdTypeResolverBuilder());
        builder.init(Id.NAME, mockIdResolver).inclusion(As.EXISTING_PROPERTY).typeProperty(propName);

        doReturn(mockIdResolver).when(builder).idResolver(any(), any(), any(), anyBoolean(), anyBoolean());

        TypeSerializer result = builder.buildTypeSerializer(config, baseType, Collections.emptyList());
        Assert.assertTrue(result instanceof AsExistingPropertyTypeSerializer);
    }

    @Test(expected = IllegalStateException.class)
    public void testBuildTypeSerializer_InvalidInclusion_ThrowsException() {
        // Using a trick to force an unsupported inclusion type if possible, 
        // but since As is an enum, we simulate an invalid state by using a builder 
        // that doesn't set inclusion if it's not handled, though the switch usually covers all.
        // However, we can try to trigger the default case if the enum had more values.
        // Since we can't easily instantiate an invalid Enum value in Java without reflection:

        StdTypeResolverBuilder builder = spy(new StdTypeResolverBuilder());
        builder.init(Id.NAME, mockIdResolver);

        // We use reflection to set an invalid inclusion if necessary, 
        // but for coverage of the 'throw' line, we assume a scenario where inclusion is null or unexpected.
        // Given the code, if _includeAs is not one of the cases, it throws.

        // Since we can't easily pass a "fake" enum, we rely on the fact that if inclusion is not set, 
        // it might default to a value not in the switch if the enum was modified.
        // For the sake of this test, we attempt to trigger it.

        // Note: In standard Jackson, all As values are covered. 
        // This test is purely to satisfy the branch coverage for the IllegalStateException.

        // Forcing a null or invalid state via reflection to hit the exception branch
        try {
            java.lang.reflect.Field field = StdTypeResolverBuilder.class.getDeclaredField("_includeAs");
            field.setAccessible(true);
            field.set(builder, null); 
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        builder.buildTypeSerializer(config, baseType, Collections.emptyList());
    }
}
